    getWaveform: {
        parameters: {
            query?: {
                /** @description Zero-based part of a multi-file audiobook to describe. Ignored for single-file items and under `span=item`. Out of range is `not-found`, matching the skip map. */
                partIndex?: number;
                /** @description What the envelope covers: one part (the default), or the whole item stitched across its parts. */
                span?: "part" | "item";
            };
            header?: {
                /** @description Previously returned `ETag`; a match answers 304 with no body. */
                "If-None-Match"?: string;
            };
            path: {
                /** @description Type-prefixed PID (e.g. `tr-01JZX5N8QW3F4V9T2B7KD3M9R6`). */
                pid: components["parameters"]["Pid"];
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The waveform, or its pending or unavailable state. */
            200: {
                headers: {
                    /** @description Validator derived from the audio essence of the file being described, which for a multi-file book is the requested part. Present on `ready` only; the other two states are not cacheable. */
                    ETag?: string;
                    /** @description `private, max-age=86400, stale-while-revalidate=604800` for `ready`, `no-store` otherwise. Not `immutable`: the URL names a pid, not the bytes, so re-analysis under the same pid has to be able to invalidate it. */
                    "Cache-Control"?: string;
                    /** @description `Cookie, Authorization`: the credential decides whether this item exists for a caller, so a cached copy is never reused across sessions on a shared browser. */
                    Vary?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Waveform"];
                };
            };
            /** @description The cached waveform is still current. It carries the same validator and freshness the body would have. */
            304: {
                headers: {
                    /** @description Validator for the cached waveform. */
                    ETag?: string;
                    /** @description The same directive the 200 carries. */
                    "Cache-Control"?: string;
                    /** @description The same credentials the 200 varies by. */
                    Vary?: string;
                    [name: string]: unknown;
                };
                content?: never;
            };
            401: components["responses"]["Unauthenticated"];
            404: components["responses"]["NotFound"];
            503: components["responses"]["CatalogMaintenance"];
        };
    };
